# Python Simulation: Tier 3 Cryptographic Supply Path Verification & Anti-Fraud Schain Engine
class Tier3SchainVerifier:
    def __init__(self):
        self.master_ads_txt = {
            "global-media-conglomerate.com": [
                {"asi": "magnite.com", "sid": "pub_99410", "rel": "DIRECT"},
                {"asi": "pubmatic.com", "sid": "pub_11042", "rel": "DIRECT"}
            ]
        }

    def verify_supply_chain_authenticity(self, domain: str, schain: dict, slot_w: int, slot_h: int) -> dict:
        # 1. Anti-Fraud Check: Pixel stuffing detection
        if slot_w <= 1 or slot_h <= 1:
            return {"status": "BLOCKED_PIXEL_STUFFING", "reason": f"Ad dimensions {slot_w}x{slot_h} indicate fraudulent hidden iframe.", "valid": False}

        # 2. Validate Schain completeness
        if schain.get("complete") != 1:
            return {"status": "BLOCKED_INCOMPLETE_SCHAIN", "reason": "Schain complete!=1; hidden intermediary hops detected.", "valid": False}

        nodes = schain.get("nodes", [])
        if not nodes:
            return {"status": "BLOCKED_EMPTY_SCHAIN", "reason": "No nodes present in Schain.", "valid": False}

        # 3. Check for multi-hop reseller arbitrage (Max 1 hop allowed for sovereign direct)
        if len(nodes) > 1:
            return {
                "status": "BLOCKED_ARBITRAGE_RESELLER",
                "reason": f"Schain has {len(nodes)} hops; exceeds direct publisher policy.",
                "valid": False
            }

        # 4. Cross-verify node 0 against master ads.txt DIRECT registry
        root_node = nodes[0]
        asi, sid = root_node.get("asi"), root_node.get("sid")

        authorized = self.master_ads_txt.get(domain, [])
        match = next((rec for rec in authorized if rec["asi"] == asi and rec["sid"] == sid), None)

        if not match:
            return {
                "status": "BLOCKED_UNAUTHORIZED_SELLER",
                "reason": f"Account '{sid}' on '{asi}' is NOT authorized in {domain}/ads.txt!",
                "valid": False
            }

        return {
            "status": "SPO_VERIFIED_DIRECT_AUTHENTIC",
            "domain": domain,
            "ssp": asi,
            "seller_id": sid,
            "relationship": match["rel"],
            "total_hops": len(nodes),
            "valid": True
        }

verifier = Tier3SchainVerifier()

# Test 1: Authentic 1-hop direct impression
valid_request = {
    "domain": "global-media-conglomerate.com",
    "slot_w": 300, "slot_h": 250,
    "schain": {"ver": "1.0", "complete": 1, "nodes": [{"asi": "magnite.com", "sid": "pub_99410", "hp": 1}]}
}

# Test 2: Pixel stuffing fraud attempt
fraud_request = {
    "domain": "global-media-conglomerate.com",
    "slot_w": 1, "slot_h": 1,
    "schain": {"ver": "1.0", "complete": 1, "nodes": [{"asi": "magnite.com", "sid": "pub_99410", "hp": 1}]}
}

print("=== TIER 3: SUPPLY PATH VERIFICATION & ANTI-FRAUD AUDIT ===\n")
res_valid = verifier.verify_supply_chain_authenticity(valid_request["domain"], valid_request["schain"], valid_request["slot_w"], valid_request["slot_h"])
print(f"✅ Authentic Direct Path: Status = {res_valid['status']}")
print(f"   Domain: {res_valid['domain']} | SSP: {res_valid['ssp']} (Rel: {res_valid['relationship']}) | Hops: {res_valid['total_hops']}\n")

res_fraud = verifier.verify_supply_chain_authenticity(fraud_request["domain"], fraud_request["schain"], fraud_request["slot_w"], fraud_request["slot_h"])
print(f"🚨 Fraud Audit Result: Status = {res_fraud['status']}")
print(f"   Reason: {res_fraud['reason']}")
